var definitions = [...]Definition{
	{Term: "the report", Definition: "The report is the research prose written for a reader of the subject: one document from a lane's text to what the run assembles at its end, named by its stage only where the stage matters — your part of the report, the report text the tool delivers to a seat on its work list, the report as `show report` prints it, which is how a seat reads it for context, and the copy assembled for the human reader once the run is over.", Seats: []string{"lens", "chair", "blue", "lane", "bench", "operator"}},
	{Term: "run directory", Definition: "The run directory is the directory that holds one run: its record, its report and the documents assembled beside it.", Seats: []string{"lens", "chair", "blue", "lane", "bench", "operator"}},
	{Term: "the record", Definition: "The record is the run's account of every act, held as events in records/record.db, and every read a seat makes is a projection of it.", Seats: []string{"lens", "chair", "blue", "lane", "bench", "operator"}},
	{Term: "run", Definition: "A run is one research question taken from setup to its outcome.", Seats: []string{"lens", "chair", "blue", "lane", "bench", "operator"}},
	{Term: "epoch", Definition: "An epoch runs from one chair sitting to the next: the chair asks the record who sits, the parties the record names sit, and the chair sits again.", Seats: []string{"lens", "chair", "blue", "lane", "bench", "operator"}},
	{Term: "sitting", Definition: "A sitting is one seat's dispatch, from the prompt the engine hands it to the envelope it returns.", Seats: []string{"lens", "chair", "blue", "lane", "bench", "operator"}},
	{Term: "failed sitting", Definition: "A failed sitting is a sitting of a seat whose work arrives as items that closed with no envelope admitted: the call returning its envelope never succeeded, because the envelope gate refused it or its schema rejected it until the harness gave up, or its agent died; it is no turn in any gap's exchange, the engine dispatches the seat again while it owes its items, and capture names each one.", Seats: []string{"operator"}},
	{Term: "exchange", Definition: "An exchange is blue's sitting on one gap followed by its assignee's audit of the answer, and k-max counts them.", Seats: []string{"lens", "chair", "blue", "lane", "bench", "operator"}},
	{Term: "seat", Definition: "A seat is one agent's place in the run, registered under a seat id whose role decides the surface it is given.", Seats: []string{"lens", "chair", "blue", "lane", "bench", "operator"}},
	{Term: "side", Definition: "A side is red or blue: red audits the report and passes or fails it, blue researches, writes and repairs it.", Seats: []string{"lens", "chair", "blue", "lane", "bench", "operator"}},
	{Term: "lens", Definition: "A lens is a red seat that audits the report for one class of defect, and the only seat that mints gaps.", Seats: []string{"lens", "chair", "blue", "lane", "bench", "operator"}},
	{Term: "chair", Definition: "The chair is red's running seat: it asks the record who sits, spot-checks the stale areas before a PASS and records red's PASS.", Seats: []string{"lens", "chair", "blue", "lane", "bench", "operator"}},
	{Term: "bench", Definition: "The bench is the seat that adjudicates the contested docket, rules on motions and stamps how the run ended.", Seats: []string{"lens", "chair", "blue", "lane", "bench", "operator"}},
	{Term: "lane", Definition: "A lane is one of blue's parallel first passes at the report, written by one researcher under one method.", Seats: []string{"blue", "lane", "bench", "operator"}},
	{Term: "synthesizer", Definition: "The synthesizer is the blue seat that merges the lanes' parts into the report by union through the record's acts, and writes the report's authored surfaces.", Seats: []string{"blue", "lane", "bench", "operator"}},
	{Term: "engine", Definition: "The engine is the workflow script that dispatches the seats the record says are ready and reads the envelopes they return.", Seats: []string{"lens", "chair", "blue", "lane", "bench", "operator"}},
	{Term: "lead session", Definition: "A run's lead session is the Claude Code session its live-run row names — the one that ran setup, or took the run over since — and the hooks attribute an agent to the run only when its payload's session_id is that session.", Seats: []string{"operator"}},
	{Term: "operator", Definition: "The operator is the person running the research, and the seat id their own commands run under.", Seats: []string{"lens", "chair", "blue", "lane", "bench", "operator"}},
	{Term: "the log", Definition: "The log is the entries a seat files for the operator with the `log` verb — a missing capability, a defect in the tooling, or friction, never a clean sitting, which is derived from having sat and filed no log entry — and none of it is debate material.", Seats: []string{"lens", "chair", "blue", "lane", "bench", "operator"}},
	{Term: "friction", Definition: "Friction is one type of log entry: something cost the seat a call, a guess or an act — a refusal, a guessed name, a misread shape, a workaround — and it notes what it expected and why, whether or not anything should change; an act no surface offers at all is a request, not friction.", Seats: []string{"lens", "chair", "blue", "lane", "bench", "operator"}},
	{Term: "missing capability", Definition: "A missing capability is an act a seat needed that no surface offers, and it goes in the log, never on the board.", Seats: []string{"lens", "chair", "blue", "lane", "bench", "operator"}},
	{Term: "citation", Definition: "A citation is a source attached to a sentence of the report with the cite verb, hashed and dated so it can be checked again.", Seats: []string{"lens", "chair", "blue", "lane", "bench", "operator"}},
	{Term: "source span", Definition: "A source span is the words of the source's own cached text a citation rests on, chosen by quoting them (found there once) or by naming their lines, and kept on the citation with the source's text around them; it is what the source says, and blue's reason for the citation is blue's account of it.", Seats: []string{"lens", "blue", "lane"}},
	{Term: "source search", Definition: "A source search is a read of cached sources' text for a regular expression, literal text, or a ranked hybrid query (BM25 and dense vectors), scoped to one source or across all cached sources in the run; each hit carries the source's sentence and whether a citation can quote that sentence as printed; a search across sources names each hit's source by URL and SHA256, a search of one source names it once for all its hits, and the search records nothing.", Seats: []string{"lens", "blue", "lane"}},
	{Term: "OCR-derived text", Definition: "OCR-derived text is a machine's reading of a scanned document's page images: deterministic, and able to misread, so a citation quoting it records the PDF page its quote sits on and is checked against that page's image.", Seats: []string{"lens", "blue", "lane", "operator"}},
	{Term: "anchor", Definition: "An anchor is the invisible token a citation, a computation or a gap leaves at its sentence in the report; a citation's or computation's is an evidence anchor, and no anchor stands bare: one leaves the report with its sentence when an edit cuts it, or alone by retire, its sentence kept.", Seats: []string{"lens", "chair", "blue", "lane", "bench", "operator"}},
	{Term: "computation", Definition: "A computation is a program blue ran and recorded as evidence: its bundle, stored by its sha256, with the output and exit status of its run, and a basis — `reproducible` when two runs wrote the same bytes, `variant` when they differed and blue stated what holds across them.", Seats: []string{"lens", "chair", "blue", "lane", "bench", "operator"}},
	{Term: "verdict", Definition: "The verdict is the chair's PASS on the board.", Seats: []string{"lens", "chair", "blue", "lane", "bench", "operator"}},
	{Term: "outcome", Definition: "The outcome is how the run ended: VERIFIED, QUALIFIED, CEILING, HALTED or UNVERIFIED.", Seats: []string{"lens", "chair", "blue", "lane", "bench", "operator"}},
	{Term: "gap", Definition: "A gap is a defect in the report that changes a conclusion or a decision a reader makes, minted onto the board by a lens.", Seats: []string{"lens", "chair", "blue", "lane", "bench", "operator"}},
	{Term: "assignee", Definition: "An assignee is the seat whose gap it is: the lens that minted the gap — it takes its author's proposal on the gap by its own act or leaves it for the bench, and owes the gap's closing.", Seats: []string{"lens", "chair", "blue", "bench", "operator"}},
	{Term: "material", Definition: "A gap is material when its class is always material, or when its class goes by grade and its current severity is medium or above, and an open material gap holds the PASS gate.", Seats: []string{"lens", "chair", "blue", "lane", "bench", "operator"}},
	{Term: "blocker", Definition: "A blocker is one entry on the list the verdict gate refuses a PASS on, with the seat whose act clears it.", Seats: []string{"lens", "chair", "bench"}},
	{Term: "current item", Definition: "A seat's current item is the one entry of its queue it is handed in full — report text owed to it, an item it owes, or a gap of its own the dispatch readies it on, with the items about that gap — beside an index of the rest; it stays current until the record shows it discharged, gone from the seat's work list after an act, and the next item is handed then.", Seats: []string{"lens", "chair", "blue", "bench", "operator"}},
	{Term: "reading", Definition: "A reading is a lens's recorded account of what one source did for one sentence of the report — `verify` of a citation, or of a source the lens found — with its outcome, its confidence and its reason; it reads the work unless the source was unreachable or the copy the tool stamped is not the work, and it holds nothing by itself: a gap a lens mints on it is the defect on the record — about the citation for a cited source's defect, quoting the sentence for a found source's — and a reading that finds the source against the sentence is its lens's reading debt until that gap stands.", Seats: []string{"lens", "chair", "blue", "lane", "bench", "operator"}},
	{Term: "retire", Definition: "To retire an anchor is to take it out of the report with the retire verb, on the record, its sentence staying word for word; a retired anchor is in no document, and a claim leaves with its sentence, by a pure cut, never by a retire.", Seats: []string{"lens", "chair", "blue", "lane", "bench", "operator"}},
	{Term: "pure cut", Definition: "A pure cut is an edit whose replacement for one or more whole sentences holds nothing of them — empty, or only whitespace and terminators; it takes every anchor of those sentences, the ones at their end included, and records each with the edit's reason, while every other edit is a rewrite, which carries every anchor of its span.", Seats: []string{"lens", "chair", "blue", "lane", "bench", "operator"}},
	{Term: "lens retirement", Definition: "Lens retirement is the record's state for a lens that has stopped finding and checking: three sittings in a row it sat through in which it mints no fresh material gap, closes no gap, records no reading and checks no computation or inquiry retire a lens that owes nothing on its work list — nothing new on a gap it minted since it last sat, no check it owns, no gap owed about a check of its that failed — and a head move does not ready a retired lens; a sitting that never closed is not one it sat through and counts neither way.", Seats: []string{"lens", "chair", "operator"}},
	{Term: "stale area", Definition: "A stale area is the area of a retired lens whose pin is behind the report head; its changes the chair has not borne are delivered to the chair on its work list, and the chair names the area in a spot-check before a PASS.", Seats: []string{"chair", "operator"}},
	{Term: "report read", Definition: "A report read is the record's evidence that the tool delivered report text into a seat's context: the tool writes one when it hands a delivery's last item, every item of it cut from the report at its head, and a read through `show report` writes none; it says the text was delivered, not that it was read, and the head of a lens's latest one in a sitting it sat through is its pin, which the lens is readied past.", Seats: []string{"lens", "chair", "bench", "operator"}},
	{Term: "disposition", Definition: "A disposition is the closing word a closing records, and it decides whether the gap closes; on a bench closure it is the statement of the side the bench sided with.", Seats: []string{"lens", "chair", "blue", "lane", "bench", "operator"}},
	{Term: "grade movement", Definition: "Grade movement is the change a lens's regrade makes to a gap's severity, likelihood or impact, weighed as the difference in mass between the two grades in either direction, and once the open gaps' movement no bench ruling on its grades has followed totals more than 2.0 the dispatch dockets each such gap for the bench and a PASS waits for its ruling, which keeps the moved grades or restores the prior ones; the bench's regrade the tool writes in a ruling's transaction is no movement.", Seats: []string{"lens", "chair", "bench", "operator"}},
	{Term: "docketing", Definition: "A docketing is the tool's record that a gap is before the bench, and why — written by the dispatch at impasse, for the open gaps' grade movement, or for the author's proposal its raiser did not take in its window, and filed by no seat — which the bench rules once, by siding with a party or remanding it, and while it stands the gap takes no proposal and its parties owe it their closings.", Seats: []string{"lens", "chair", "blue", "bench", "operator"}},
	{Term: "tombstone", Definition: "A tombstone is the row the tool writes on a gap a bench ruling decided, for either side, and on a gap whose stated text blue applied verbatim: while a ruling's stands, a mint of the gap's class on its sentence, inquiry, citation, question part or section and every proposal on the gap are refused, and blue's reword or cut of the sentence, a reword, cut or retire of the anchor the gap is about, the inquiry's next fate or the question part's next coverage ends it; the bench's application ends none.", Seats: []string{"lens", "chair", "blue", "bench", "operator"}},
	{Term: "estopped", Definition: "An estopped gap is one a standing ruling tombstone protects, which the work list names with the ruling and the act that ends it, and which no seat may re-raise while it stands.", Seats: []string{"lens", "chair", "blue", "bench", "operator"}},
	{Term: "relief", Definition: "Relief is the order the bench records when it grants a petition: what the seats it binds must or must not do, with whom it binds, carried from the ruling to every seat's work list.", Seats: []string{"lens", "chair", "blue", "lane", "bench", "operator"}},
	{Term: "scorecard", Definition: "A scorecard is the numbers a seat is measured on, computed from the record: red's for the lenses and the chair, blue's for blue's seats, the bench's for the bench.", Seats: []string{"lens", "chair", "blue", "lane", "bench", "operator"}},
	{Term: "occasion", Definition: "A sitting's occasion is what it was convened to do — the question put to the seat, as against the seat id, which says who was asked — and only the bench carries one, because its five sittings share a single id.", Seats: []string{"bench"}},
	{Term: "inquiry", Definition: "An inquiry is one question the research could take up — proposed by blue with the hypothesis that would be true if it paid off, recorded with the fate that says what became of it — judged open while its fate is proposed or underway, which holds the PASS until blue settles it; wanting while an open material gap is about it; unchecked once settled with no check standing, which holds the PASS until the logic lens checks its latest fate; and sound while that check stands, which a new fate or any gap minted about it, material or not, unseats.", Seats: []string{"lens", "chair", "blue", "lane", "bench", "operator"}},
	{Term: "question part", Definition: "A question part is one part of the question the run was asked — split out by blue in the subject's terms, recorded with its coverage: covered where the report answers it, not obtained where the sources that would answer it could not be obtained, excluded where it lies outside the report's answer — judged open while it has no coverage, which holds the PASS until blue records one, as a question split into no part does; wanting while an open material gap is about it; unchecked once covered with no check standing, which holds the PASS until the logic lens checks its latest coverage; and sound while that check stands, a PASS over any part not covered deriving QUALIFIED.", Seats: []string{"lens", "chair", "blue", "lane", "bench", "operator"}},
	{Term: "reopened", Definition: "A citation or computation is reopened when a rewrite changes its sentence after a check and no sitting opened since has checked it — it is unchecked again; its owning lens owes the check and is the seat readied for it — the evidence lens for a citation, the lens that owns computations for a computation — a check by any lens from a sitting opened after the rewrite clears it, and a PASS waits until one does; a pure cut reopens nothing, since the anchors it takes leave the report with their checks.", Seats: []string{"lens", "chair", "blue", "lane", "operator"}},
	{Term: "unchecked", Definition: "A citation or computation is unchecked when no check of the sentence the report carries stands: nobody has checked it, or it is reopened; its owning lens owes the check and is readied for it, and a PASS waits until one is recorded.", Seats: []string{"lens", "chair", "blue", "lane", "operator"}},
	{Term: "failed check", Definition: "A failed check is a standing check of a citation or computation that failed — a lens judged the computation's sentence unsound, or every reading of the citation since its sentence last changed read nothing of the cited work — which holds the PASS and is cleared by no bench ruling; it obliges the seat whose check failed to mint a gap about the anchor; a seat's close of the gap that carries a failed check is refused while the check stands, and a closing ruling of the bench closes that gap while the check still holds the PASS; and the check clears when an edit changes its sentence, when blue retires the anchor, or when the anchor is checked and holds — for a computation by the judging lens's own later check, since another lens's check beside it is a disagreement, and for an unread citation by any lens's reading of the work; and the check clearing admits the close of a gap whose check kind is source or computation only under its live-answer demand, which holds while the gap's subject stands in the report and which, while it stands, a live answer of that kind placed as its answer meets, as does the later check of the anchor the gap is about by the seat whose check the gap carries that holds.", Seats: []string{"lens", "chair", "blue", "lane", "bench", "operator"}},
	{Term: "reading debt", Definition: "A reading debt is a lens's standing reading that finds a source against its sentence — a citation's source that refutes the sentence or says nothing of it, or a source the lens found that refutes the sentence it was read against — with no gap of its class on the subject: the lens's unfinished promise, a PASS blocker on the chair's list with the lens named, which the lens clears by minting that gap on the reading or by reading the subject again, and which blue's edit of the cited sentence, retire of the citation, or removal of the sentence a found source was read against discharges; from the mint on the gap's grade alone holds the PASS.", Seats: []string{"lens", "chair", "blue", "lane", "bench", "operator"}},
}
